with.tags:
type=ref,event=branch,prefix=${{ inputs.prefix }}
type=pep440,pattern={{version}}
type=pep440,pattern={{major}}.{{minor}}
type=raw,value=${{ inputs.version }},enable=${{ inputs.version != null }}
type=raw,value=latest,enable=${{ steps.check-latest.outputs.IS_LATEST }}

steps.run:
payload=$(
    jq --arg version "$VERSION" --arg branch "$BRANCH" --null-input '
      {
        "event_type": "deploy-load-test",
        "client_payload": {
          "branch": $branch,
          "version": $version
        }
      }
    '
)

gh api /repos/saleor/saleor-multitenant/dispatches --input - <<< "$payload"

with.script:
// 1. Get all open PRs - pagination is needed or otherwise we would retrieve only first 30
const pulls = await github.paginate(github.rest.pulls.list, {
  owner: context.repo.owner,
  repo: context.repo.repo,
  state: 'open'
});

// 2. Select PRs with "test deployment" label and extract their source branches
const branches = pulls
  .filter(pr => pr.labels.some(label => label.name === 'test deployment'))
  .map(pr => pr.head.ref);

// 3. Deduplicate (in case there are multiple PRs with the same source branch) and then slugify the branch names
return [...new Set(branches)].map(ref =>
  ref.toLowerCase()
    .replace(/[^a-z0-9._]/g, '-')    // replace any character except [0-9, a-z, .,_] with dash
    .replace(/^-+/, '')              // remove leading -
    .slice(0, 63)                    // limit to 63
    .replace(/-+$/, '')              // remove trailing -
);

steps.run:
# Falls back to `GITHUB_REF_NAME` when base is undefined which
# means we merged into `main` or 3.x
base=${GITHUB_BASE_REF:-$GITHUB_REF_NAME}
base=${base#refs/heads/}

# Fall back the head to `GITHUB_REF_NAME` when head is not defined.
# That means we merged onto main/3.x
head=${GITHUB_HEAD_REF:-$GITHUB_REF_NAME}
head=${head#refs/heads/}

is_release=
if [[ "$head" =~ ^[0-9]\.[0-9]+$ ]] || [[ "$head" == "main" ]]; then
  echo "Will save cache to $head (if relevant)" >&2
  is_release=1
else
  echo "Will skip caching: $head is not a main/release branch" >&2
fi

{
  echo "base=$base"
  echo "head=$head"
  echo "is-release=$is_release"
} >> "$GITHUB_OUTPUT"
